export type TagValue = string | { readonly tag: string };

export function encodeTags(values: readonly TagValue[]): string {
  const normalized = values.map((value): { tag: string } => {
    if (typeof value === "string") {
      return { tag: value };
    }
    if (value === null || typeof value !== "object" || Array.isArray(value)) {
      throw new TypeError("Invalid tag value");
    }
    const keys = Object.keys(value);
    if (keys.length < 1 || keys[0] !== "tag" || typeof value.tag !== "string") {
      throw new TypeError("Invalid tag object");
    }
    return { tag: value.tag };
  });
  return JSON.stringify(normalized);
}

