import { encodeTags, TagValue } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  assert(Object.is(actual, expected), `${message}: expected ${String(expected)}, got ${String(actual)}`);
}

function throwsTypeError(fn: () => void, message: string): void {
  let error: unknown;
  try { fn(); } catch (caught) { error = caught; }
  assert(error instanceof TypeError, message);
}

equal(encodeTags([]), '[]', 'encodes empty input');
equal(encodeTags(['a', { tag: 'b' }, '', 'a']), '[{"tag":"a"},{"tag":"b"},{"tag":""},{"tag":"a"}]', 'normalizes values while preserving order and duplicates');

const nullPrototype = Object.create(null) as { tag: string };
nullPrototype.tag = 'plain';
equal(encodeTags([nullPrototype]), '[{"tag":"plain"}]', 'accepts a non-null object with exactly tag');

const objectValue = Object.freeze({ tag: 'stable' });
const values: readonly TagValue[] = Object.freeze(['first', objectValue]);
const before = JSON.stringify(values);
equal(encodeTags(values), '[{"tag":"first"},{"tag":"stable"}]', 'encodes frozen input');
equal(JSON.stringify(values), before, 'does not mutate input values');

const invalid: unknown[] = [
  null,
  undefined,
  3,
  true,
  ['tag'],
  {},
  { tag: 1 },
  { tag: 'x', extra: true },
  { other: 'x' }
];
for (const value of invalid) {
  throwsTypeError(() => encodeTags([value as TagValue]), `rejects invalid value ${String(value)}`);
}

